if (e.KeyCode == Keys.Enter && ExpFileList.SelectedItems.Count > 0)
            {
                string name = ExpFileList.SelectedItems[0].Text;
                var csi = (CShItem)ExpFileList.SelectedItems[0].Tag;

                if (csi.IsFolder)
                {
                    if (csi.Path.StartsWith(":"))
                        ExpListItemDoubleClick?.Invoke(csi.DisplayName, csi);
                    else
                        ExpListItemDoubleClick?.Invoke(csi.Path, csi);
                }
                else
                {
                    string path = csi.Path;
                    try
                    {
                        if (name == Path.GetFileName(path))
                            Process.Start(csi.Path);
                    }
                    catch (Exception ex)
                    {
                        MessageBox.Show(ex.Message, "Error in starting application", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                }
            }

