                Point pt = new Point(e.X, e.Y);
                ListViewItem tn = ExpFileList.GetItemAt(e.X, e.Y);

                if (tn != null && ExpFileList.SelectedItems.Count > 0)
                {
                    var itms = new CShItem[ExpFileList.SelectedItems.Count];
                    for (int i = 0; i < ExpFileList.SelectedItems.Count; i++)
                        itms[i] = (CShItem)ExpFileList.SelectedItems[i].Tag;

                    CMInvokeCommandInfoEx cmi;
                    bool allowRename = ExpFileList.SelectedItems.Count <= 1; //Don't allow rename of more than 1 item

                    if (m_WindowsContextMenu.ShowMenu(Handle, itms, MousePosition, allowRename, out cmi))
                    {
                        byte[] cmdBytes = new byte[256];
                        m_WindowsContextMenu.winMenu.GetCommandString(cmi.lpVerb.ToInt32(), (int)GCS.VERBA, 0, cmdBytes, 256);
                        string cmdName = SzToString(cmdBytes).ToLowerInvariant();

                        if (cmdName.Equals("rename"))
                        {
                            ExpFileList.LabelEdit = true;
                            tn.BeginEdit();
                        }
                        else
                        {
                            string strPath = itms[0].Parent == CShItem.GetDeskTop()
                                ? Environment.GetFolderPath(Environment.SpecialFolder.Desktop)
                                : itms[0].Parent.Path;

                            m_WindowsContextMenu.InvokeCommand(m_WindowsContextMenu.winMenu, (UInt32)cmi.lpVerb.ToInt32(), strPath, pt);
                        }

                        Marshal.ReleaseComObject(m_WindowsContextMenu.winMenu);
                    }
                }
                else
                {
                    GetFolderMenu(MousePosition);
                }
            }

